    if maxSteps - steps >= closeReserve {
      phase4Limit := maxSteps - closeReserve;
    }

    // Inner constrained loop (same structure as Phase 2)
    while insideConstrainedOut && steps < phase4Limit
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase4Limit - steps
    {
      if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
        var cg4, ci4, cc4 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        steps := steps + 1;
        generated := cg4;
        insideConstrainedOut := ci4;
        currentConstrainedOut := cc4;
        hasCompletedSpan := true;
      } else {
        var cp4 := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next4: Token;
        if |currentConstrainedOut| < minSpanTokens {
          next4 := helpers.SafeBoostedConstrainedStep(lm, parser, cp4, currentConstrainedOut, opTokens, 4.0, eosToken);
        } else {
          next4 := helpers.ConstrainedStep(lm, parser, cp4, currentConstrainedOut, eosToken);
        }
        steps := steps + 1;
        if next4 == eosToken { break; }
        var ag4, ai4, ac4 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next4);
        generated := ag4;
        insideConstrainedOut := ai4;
        currentConstrainedOut := ac4;
      }
    }

    // Close with remaining budget
    if insideConstrainedOut && steps < maxSteps {
      var rem4 := maxSteps - steps;
      var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem4);
      generated := wg4;
      insideConstrainedOut := wi4;
      currentConstrainedOut := wc4;
      steps := steps + rem4;
    }
  }
}

// ── Phase 5: Final safety close ───────────────────────────────────────────────
if insideConstrainedOut && steps < maxSteps {
  var rem5 := maxSteps - steps;
  if rem5 > 0 {
    var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem5);
    generated := wg5;
    insideConstrainedOut := wi5;
    currentConstrainedOut := wc5;
    steps := steps + rem5;
  }
}

cost := steps;
